def build_xlsx_fixture(path: Path | None = None) -> Path:
    """生成虚构 XLSX 多工作表夹具。"""
    if path is None:
        path = FIXTURES_DIR / "sample_workbook.xlsx"

    sheets: dict[str, pd.DataFrame] = {
        "中国大陆": pd.DataFrame(MAINLAND_ROWS, columns=MAINLAND_COLUMNS),
        "中国香港": pd.DataFrame(HK_ROWS, columns=HK_COLUMNS),
        "美国": pd.DataFrame(US_ROWS, columns=US_COLUMNS),
        "英国": pd.DataFrame(UK_ROWS, columns=UK_COLUMNS),
        "新加坡": pd.DataFrame(SG_ROWS, columns=SG_COLUMNS),
        "低年级项目-全球版": pd.DataFrame(
            JUNIOR_GLOBAL_ROWS, columns=JUNIOR_GLOBAL_COLUMNS
        ),
        "低年级项目-美国&香港-公司官网": pd.DataFrame(
            JUNIOR_OFFICIAL_ROWS, columns=JUNIOR_OFFICIAL_COLUMNS
        ),
        # 不支持的工作表（应被 parse_workbook 跳过）
        "临时表-不该被解析": pd.DataFrame(UNSUPPORTED_ROWS, columns=UNSUPPORTED_COLUMNS),
    }

    with pd.ExcelWriter(path, engine="openpyxl") as writer:
        for name, df in sheets.items():
            df.to_excel(writer, sheet_name=name, index=False)

    return path


def build_csv_fixture(path: Path | None = None) -> Path:
    """生成虚构 CSV 单表夹具（中国大陆布局）。"""
    if path is None:
        path = FIXTURES_DIR / "sample_mainland.csv"

    df = pd.DataFrame(MAINLAND_ROWS, columns=MAINLAND_COLUMNS)
    df.to_csv(path, index=False, encoding="utf-8-sig")
    return path


def main() -> None:
    xlsx = build_xlsx_fixture()
    csv_file = build_csv_fixture()
    print(f"已生成 XLSX 夹具：{xlsx}")
